local function getEggSize(model) for _,a in ipairs({"Size","EggSize","Scale","WeightKg","Weight"}) do local v=model:GetAttribute(a) if typeof(v)=="number" then return v end end local ok,_,sz=pcall(function() return model:GetBoundingBox() end) if ok and sz then return sz.Magnitude end return 0 end
local function getEggsInZone(zoneName) local zb=getZoneBuildsFolder() if not zb then return {} end local zm=zb:FindFirstChild(zoneName) if not zm then return {} end local er=zm:FindFirstChild("Eggs") or zm local out={} for _,v in ipairs(er:GetChildren()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out,v) end end if #out==0 then for _,v in ipairs(er:GetDescendants()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out,v) end end end if bigEggPriority then table.sort(out,function(a,b) return getEggSize(a)>getEggSize(b) end) end return out end
local function getEggHealth(m) if m:GetAttribute("Health") then return m:GetAttribute("Health") end return nil end
local function equipPickaxe() local char=plr.Character if not char then return nil end for _,t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") and t.Name:lower():find("pickaxe") then t.Parent=char return t end end for _,t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") then t.Parent=char return t end end return char:FindFirstChildOfClass("Tool") end
eggAcc:Toggle({Title="Break Egg", Desc="Auto break", Flag="BreakEgg_LIB", Default=false, Callback=function(v) breakOn=v if v then if not selectedEggZone then Window.Notify("ERR","Pilih Zone",Color3.fromRGB(248,113,113),2) return end task.spawn(function() while breakOn do if halloweenActive or bloodMoonActive then task.wait(0.5) continue end local eggs=getEggsInZone(selectedEggZone) if #eggs==0 then task.wait(1) continue end for _,egg in ipairs(eggs) do if not breakOn or halloweenActive or bloodMoonActive then break end local p,b=getOffsetPos(egg) if not p then local bp=getBasePos(egg) if bp then p=V3(bp.X,3.5,bp.Z+3) b=V3(bp.X,3.5,bp.Z) end end if not p then continue end walkDirect(p,b,false) equipPickaxe() while breakOn and egg.Parent and not halloweenActive and not bloodMoonActive do local h=getEggHealth(egg) if h and h<=0 then break end task.wait(0.15) end task.wait(0.2) end end end) end end})

