local bloodAcc=EventAPI:Accordion({Title="BLOODMOON EVENT - NEW", Desc="BloodMoonPumpkinKings reset+break terdekat", Open=true})
bloodAcc:Paragraph({Title="Analysis Logic", Desc="Deteksi workspace.BloodMoonPumpkinKings -> reset 1x -> walkto terdekat -> break egg (pickaxe) -> pause steal/break"})
bloodAcc:Toggle({Title="Auto BloodMoon", Flag="BloodMoon_LIB", Default=false, Callback=function(v) bloodMoonEnabled=v if v then task.spawn(function() while bloodMoonEnabled do local tgt,pos=getClosestBloodMoon() if tgt and pos then lastBloodSeen=tick() if not bloodMoonActive then bloodMoonActive=true hasResetBlood=false Window.Notify("BLOODMOON","PumpkinKings muncul! Reset 1x",Color3.fromRGB(180,0,0),3) end if not hasResetBlood then hasResetBlood=true resetCharOnce() task.wait(2) continue end walkDirect(V3(pos.X,3.5,pos.Z),pos,false) equipPickaxe() local st=tick() while bloodMoonEnabled and tgt.Parent and tick()-st<12 do local h=getEggHealth(tgt) if h and h<=0 then break end task.wait(0.2) end else if bloodMoonActive and tick()-lastBloodSeen>10 then bloodMoonActive=false hasResetBlood=false Window.Notify("BLOODMOON","Selesai 10s -> lanjut",DIM,3) end task.wait(0.5) end end end) else bloodMoonActive=false hasResetBlood=false end end})

plr.CharacterAdded:Connect(function(char) task.wait(0.5) local hum=char:WaitForChild("Humanoid",15) if hum then sliderSpeed=hum.WalkSpeed end if espEnabled then task.wait(0.5) refreshAllEsp() end end)
RunService.Heartbeat:Connect(function() local hum=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if hum and math.abs(hum.WalkSpeed-sliderSpeed)>0.1 then hum.WalkSpeed=sliderSpeed end end)
